using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S1.Dynamics.Symbolic.PermutativeLifts;

internal sealed class EssentialPeriodStructureDocument : IScribeDocumentDefinition
{
    private const string Owner = "D5/S1/Dynamics/Symbolic/PermutativeLifts/EssentialPeriodStructure.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Essential periods from actual colored skeletons.",
        H("Essential periods from actual colored skeletons"),
        Blocks(
            Describe.Lean(DescribeId.Create("coordinate-periodic"), DeclarationHandle.Create(Owner + "CoordinatePeriodic"),
                H("CoordinatePeriodic"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For an arbitrary alphabet and a two-sided point x, site i is p-periodic exactly when x(i+kp)=x(i) for every signed integer k. The predicate itself permits period zero; positivity is imposed separately in essential periods and period structures."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("sites"), DeclarationHandle.Create(Owner + "sites"),
                H("sites"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The actual period-p skeleton mask is the set of all signed coordinates satisfying the full coordinate periodicity condition. It is not a finite sampled approximation."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("color"), DeclarationHandle.Create(Owner + "color"),
                H("color"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The colored period-p skeleton has the actual letter x(i) at every periodic site and a hole, represented by none, everywhere else. Keeping the letters as well as the mask is necessary for essential-period extraction."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("coordinate-periodic-of-dvd"), DeclarationHandle.Create(Owner + "coordinate_periodic_of_dvd"),
                H("coordinate periodic of dvd"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("If p divides q, every actual p-periodic coordinate is q-periodic. The integer multiplier in q is absorbed into the signed multiple already quantified in the coordinate condition."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("coordinate-periodic-translate"), DeclarationHandle.Create(Owner + "coordinate_periodic_translate"),
                H("coordinate periodic translate"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("A p-periodic site remains p-periodic after translation by any signed multiple of p. The translated site carries the same actual letter."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("coordinate-periodic-translate-iff"), DeclarationHandle.Create(Owner + "coordinate_periodic_translate_iff"),
                H("coordinate periodic translate iff"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Translation by a signed multiple of p preserves and reflects membership in the actual p-skeleton, using both positive and negative translations."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("color-eq-some-iff"), DeclarationHandle.Create(Owner + "color_eq_some_iff"),
                H("color eq some iff"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("A colored skeleton takes value some a at a coordinate exactly when that coordinate is periodic and its actual letter equals a. This bridge exposes both the mask and the letter content."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("value-eq-of-color-period"), DeclarationHandle.Create(Owner + "value_eq_of_color_period"),
                H("value eq of color period"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("A global signed period q of a colored p-skeleton preserves the actual letters along every q-translate of each p-periodic coordinate. The global colored equality is iterated in both signed directions."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("coordinate-translate-of-super-color-period"), DeclarationHandle.Create(Owner + "coordinate_translate_of_super_color_period"),
                H("coordinate translate of super color period"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("When p divides r, a period q of the colored r-skeleton translates every p-periodic site to another p-periodic site. The proof compares actual letters at all p-translates using the larger skeleton; mask nesting alone is insufficient."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("color-periodic-of-dvd"), DeclarationHandle.Create(Owner + "color_periodic_of_dvd"),
                H("color periodic of dvd"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("When p divides r, every global signed period of the colored r-skeleton is also a period of the colored p-skeleton. Both membership and its complement are preserved, and actual letters agree on the mask."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("iterate-unit-shift"), DeclarationHandle.Create(Owner + "iterate_unit_shift"),
                H("iterate unit shift"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The n-th iterate of the actual unit shift on a two-sided point is the actual shift by the natural integer n. This connects Mathlib dynamical minimal periods to the concrete signed-coordinate convention."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("is-periodic-pt-unit-shift-iff"), DeclarationHandle.Create(Owner + "isPeriodicPt_unit_shift_iff"),
                H("isPeriodicPt unit shift iff"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The n-periodic-point condition under the unit shift is equivalent to ordinary additive periodicity by the integer n. The equivalence respects the actual FullShift action convention."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("color-self-periodic"), DeclarationHandle.Create(Owner + "color_self_periodic"),
                H("color self periodic"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The actual colored p-skeleton is globally p-periodic, including its holes. Periodicity of each occupied coordinate preserves its letter, while signed translation preserves the skeleton mask."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("least-period"), DeclarationHandle.Create(Owner + "leastPeriod"),
                H("leastPeriod"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The extracted period is Mathlib minimalPeriod for the colored p-skeleton under the unit shift. It depends on the full colored skeleton, not only on a mask or on a word presentation."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("least-period-pos"), DeclarationHandle.Create(Owner + "leastPeriod_pos"),
                H("leastPeriod pos"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Every positive original skeleton period gives a positive extracted minimal period. This follows from the actual periodic-point bridge and Mathlib positivity of minimal periods."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("least-period-dvd"), DeclarationHandle.Create(Owner + "leastPeriod_dvd"),
                H("leastPeriod dvd"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The extracted colored-skeleton minimal period divides the original natural skeleton period. The original colored skeleton is itself globally periodic, so Mathlib minimal-period divisibility applies."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("color-least-period-periodic"), DeclarationHandle.Create(Owner + "color_leastPeriod_periodic"),
                H("color leastPeriod periodic"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The actual colored p-skeleton is globally periodic by its extracted minimal natural period. This is an actual coordinate-period statement derived from the dynamical minimal-period API."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("sites-least-period-eq"), DeclarationHandle.Create(Owner + "sites_leastPeriod_eq"),
                H("sites leastPeriod eq"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Passing from p to its colored-skeleton minimal period preserves the entire actual periodic-coordinate set. Divisibility gives one inclusion, while preservation of actual letters under the colored minimal period gives the converse."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("color-least-period-eq"), DeclarationHandle.Create(Owner + "color_leastPeriod_eq"),
                H("color leastPeriod eq"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Passing to the extracted minimal period preserves the whole colored skeleton, including actual letters and holes at every signed coordinate. This is stronger than an equality of uncolored masks."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("essential-period"), DeclarationHandle.Create(Owner + "EssentialPeriod"),
                H("EssentialPeriod"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("A source essential period is positive, has a nonempty actual periodic skeleton, and equals the least global period of that colored skeleton. Nonemptiness excludes the initially empty skeleton of a nonconstant point."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("least-period-essential"), DeclarationHandle.Create(Owner + "leastPeriod_essential"),
                H("leastPeriod essential"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Every positive period with nonempty actual skeleton supplies an essential period after least-period extraction. The skeleton and its colors are unchanged; no essentiality hypothesis on the original period is inserted."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("least-period-dvd-of-dvd"), DeclarationHandle.Create(Owner + "leastPeriod_dvd_of_dvd"),
                H("leastPeriod dvd of dvd"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Nested original periods give extracted colored-skeleton periods that divide one another. A period of the larger colored skeleton is transported to the smaller colored skeleton and Mathlib minimal-period divisibility is reused."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("least-periods-dvd-of-le"), DeclarationHandle.Create(Owner + "leastPeriods_dvd_of_le"),
                H("leastPeriods dvd of le"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For a scale in which each period divides the next, extracted least periods at any two ordered levels retain divisibility. This is finite induction over levels, preserving the actual colored-skeleton notion."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("least-periods-monotone"), DeclarationHandle.Create(Owner + "leastPeriods_monotone"),
                H("leastPeriods monotone"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The extracted least-period sequence is monotone for any positive divisibility scale. Each positive later extracted period is a multiple of the preceding one, so divisibility implies numerical order."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("least-periods-unbounded"), DeclarationHandle.Create(Owner + "leastPeriods_unbounded"),
                H("leastPeriods unbounded"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For an aperiodic two-sided point whose positive skeleton scale covers every coordinate, the extracted least periods are unbounded. If bounded by K, every positive extracted period divides K factorial, and coordinate coverage would make that positive factorial a global shift period."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("period-structure"), DeclarationHandle.Create(Owner + "PeriodStructure"),
                H("PeriodStructure"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The primary-source period structure consists of strictly increasing positive essential periods, divisibility of each period into the next, and coverage of every signed coordinate by the actual skeletons. Essentiality includes a nonempty skeleton and the colored minimal-period equality."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("skeleton-density"), DeclarationHandle.Create(Owner + "skeletonDensity"),
                H("PeriodStructure skeletonDensity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Along a genuine period structure of a binary point, the normalized skeleton density is the actual periodic phase count divided by its positive essential period. Positivity is supplied by the structure, not by an extra caller assumption."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("exists-period-structure"), DeclarationHandle.Create(Owner + "exists_period_structure"),
                H("exists period structure"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Any aperiodic point with a positive, nonempty, nested and covering skeleton scale admits a genuine source period structure. Least-period extraction preserves colors and divisibility; aperiodicity forces unboundedness; Mathlib supplies a strictly increasing cofinal index subsequence, removing repeated extracted periods. Every source clause is proved, while the hypotheses on the initial scale remain explicit. Public escape registrations remain unfinished under https://github.com/the-omega-institute/trureturing/issues/24726; a successful mathematical build does not constitute declared_validated registration evidence."))), DescribeRole.Theorem)),
            [ DocumentEdge.Dependency.Create(GidRef.Create("D5/S1/Dynamics/Symbolic/PermutativeLifts/PeriodicSkeletonDensity")) ]));
}
